import React, { useCallback, useEffect, useState } from 'react';
import {
  fetchSchoolAlerts,
  patchSchoolAlert,
  SchoolAlertItem,
  getErrorMessage
} from '../api';

const statusOptions = [
  { value: 'pending', label: '待处理' },
  { value: 'contacted', label: '已联系' },
  { value: 'referred', label: '已转介' },
  { value: 'closed', label: '已关闭' },
  { value: 'false_positive', label: '误报' }
] as const;

const SchoolAlerts: React.FC = () => {
  const [alerts, setAlerts] = useState<SchoolAlertItem[]>([]);
  const [filter, setFilter] = useState<string>('');
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchSchoolAlerts(filter || undefined);
      setAlerts(data.alerts);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => {
    load();
  }, [load]);

  const handleStatus = async (id: string, status: string) => {
    try {
      await patchSchoolAlert(id, { status });
      await load();
    } catch (e) {
      alert(getErrorMessage(e));
    }
  };

  return (
    <div className="school-alerts">
      <div className="school-toolbar">
        <h2>风险告警</h2>
        <select value={filter} onChange={(e) => setFilter(e.target.value)}>
          <option value="">全部状态</option>
          {statusOptions.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
        <button type="button" className="save-care-btn" onClick={load}>
          刷新
        </button>
      </div>

      {loading && <p className="muted">加载中…</p>}
      {!loading && alerts.length === 0 && <p className="muted">暂无告警记录</p>}

      <div className="school-alert-list">
        {alerts.map((a) => (
          <article key={a.id} className={`school-alert-card level-${a.level}`}>
            <div className="school-alert-head">
              <strong>{a.studentMask}</strong>
              <span className={`badge ${a.level}`}>{a.level === 'critical' ? '危急' : a.level === 'high' ? '高危' : '关注'}</span>
              <span className="badge status">{a.status}</span>
            </div>
            <p>{a.summary}</p>
            {a.riskKeywords.length > 0 && (
              <div className="school-tags">
                {a.riskKeywords.map((k) => (
                  <span key={k} className="group-tag">
                    {k}
                  </span>
                ))}
              </div>
            )}
            <small className="muted">
              {new Date(a.dialogTime).toLocaleString('zh-CN')} · 机构 {a.orgId}
            </small>
            <div className="school-alert-actions">
              <select
                defaultValue={a.status}
                onChange={(e) => handleStatus(a.id, e.target.value)}
              >
                {statusOptions.map((o) => (
                  <option key={o.value} value={o.value}>
                    标记为 {o.label}
                  </option>
                ))}
              </select>
            </div>
          </article>
        ))}
      </div>
    </div>
  );
};

export default SchoolAlerts;
